{
  "findings": [
    {
      "check_id": "CKV_AZURE_131",
      "title": "Azure Activity Log Alert is not enabled for all categories",
      "resource": "azurerm_monitor_activity_log_alert.negative1",
      "severity": "MEDIUM",
      "explanation": "The activity log alert is not monitoring all critical categories, potentially missing important security events."
    }
  ],
  "patched_code": "resource "azurerm_monitor_activity_log_alert" "negative1" {
  name                = "example-activitylogalert"
  resource_group_name = azurerm_resource_group.example.name
  location            = azurerm_resource_group.example.location
  scopes              = [azurerm_resource_group.example.id]
  description         = "Negative sample"

  criteria {
    resource_id    = azurerm_storage_account.to_monitor.id
    operation_name = "Microsoft.Network/networkSecurityGroups/delete"
    category       = "Administrative"
  }

  criteria {
    category = "Security"
  }

  criteria {
    category = "ServiceHealth"
  }

  criteria {
    category = "ResourceHealth"
  }

  criteria {
    category = "Policy"
  }

  action {
    action_group_id = azurerm_monitor_action_group.main.id

    webhook_properties = {
      from = "terraform"
    }
  }
}
",
  "fix_summary": "Added criteria blocks to monitor 'Security', 'ServiceHealth', 'ResourceHealth', and 'Policy' categories in addition to the existing 'Administrative' category."
}
